'use strict';
const VERSION=1, STORE='records', DBNAME='band-archive-v1';
const TYPES={bands:'バンド',members:'メンバー',songs:'楽曲',releases:'作品',shows:'ライブ',events:'出来事'};
const SCHEMAS={bands:[['name','バンド名','text',true],['formed','結成年月日','date'],['genre','ジャンル','text'],['photoUrls','写真URL（1行に1枚）','textarea'],['description','紹介文','textarea']],members:[['name','名前','text',true],['start','加入日','date'],['end','脱退日','date'],['role','担当パート','text'],['birthday','生年月日','date'],['birthplace','出身地','text'],['instruments','使用楽器','text'],['solo','ソロ・別プロジェクト','textarea'],['photoUrls','写真URL（1行に1枚）','textarea'],['description','経歴・紹介','textarea']],songs:[['name','曲名','text',true],['date','発表日','date'],['writer','作詞','text'],['composer','作曲','text'],['arranger','編曲','text'],['releaseId','収録作品','ref:releases'],['duration','演奏時間（例 4:32）','text'],['bpm','テンポ（BPM）','number'],['key','キー','text'],['genre','ジャンル','text'],['mvUrl','MVのURL','url'],['photoUrls','写真URL（1行に1枚）','textarea'],['lyrics','歌詞','textarea'],['description','紹介文','textarea']],releases:[['name','作品名','text',true],['date','発売日','date'],['kind','形態（アルバム・シングル等）','text'],['label','レーベル','text'],['catalog','規格品番','text'],['price','発売価格','number'],['sales','売上枚数','number'],['tracklist','収録曲メモ（旧形式・任意）','textarea'],['coverUrl','ジャケット画像URL','url'],['photoUrls','写真URL（1行に1枚）','textarea'],['description','作品紹介','textarea']],shows:[['name','公演名','text',true],['date','公演日','date'],['venue','会場','text'],['tour','ツアー名','text'],['attendance','動員数','number'],['ticketPrice','一律チケット価格（区分未設定の場合）','number'],['ticketTiers','席種別チケット（1行：席種,価格,販売枚数）','textarea'],['revenue','興行収入（自動計算）','calculated'],['setlist','セットリスト（1行1曲）','textarea'],['photoUrls','写真URL（1行に1枚）','textarea'],['description','概要','textarea']],events:[['name','出来事の見出し','text',true],['date','発生日','date'],['category','分類','text'],['sourceUrl','参照URL','url'],['photoUrls','写真URL（1行に1枚）','textarea'],['description','詳細','textarea']]};
let db,view='home',mode='management',editId=null,records=[],filter='';let archiveYear='',archiveFacet='',archiveSort='date-desc';let timelineYear='',timelineType='all',timelineMetric='shows',reportYear='';let archiveLayout='list';try{archiveLayout=localStorage.getItem('band-archive-layout')==='grid'?'grid':'list'}catch(e){}
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function openDB(){return new Promise((res,rej)=>{const req=indexedDB.open(DBNAME,VERSION);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains(STORE)){const s=d.createObjectStore(STORE,{keyPath:'id'});s.createIndex('type','type')}};req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
function txn(method,action){return new Promise((res,rej)=>{const t=db.transaction(STORE,method),s=t.objectStore(STORE),r=action(s);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function refresh(){records=await txn('readonly',s=>s.getAll());render()}
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',2800)}
const title=r=>r.name||'名称未設定';const date=r=>r.date||r.formed||r.start||'';
function nav(v){view=v;editId=null;filter='';archiveYear='';archiveFacet='';archiveSort='date-desc';render();window.scrollTo(0,0)}
function render(){document.querySelectorAll('.bottom button').forEach(b=>b.classList.toggle('active',b.dataset.view===view||(view==='more'&&b.dataset.view==='more')));$('modeButton').textContent=({management:'管理モード',official:'公式サイト',encyclopedia:'百科事典'})[mode]+' ▾';let html='';if(view==='home')html=home();else if(view==='timeline')html=timeline();else if(view==='more')html=more();else if(view==='settings')html=settings();else if(view==='statistics')html=statistics();else if(view==='search')html=searchPage();else if(view==='form')html=formPage();else if(view==='detail')html=recordDetail();else if(TYPES[view])html=listPage(view);else html=home();$('app').innerHTML=html;attach()}
function counts(t){return records.filter(r=>r.type===t).length}
function linkedSongs(release){const songs=records.filter(r=>r.type==='songs'&&r.releaseId===release.id);const order=Array.isArray(release.trackOrder)?release.trackOrder:[];return songs.sort((a,b)=>{const ai=order.indexOf(a.id),bi=order.indexOf(b.id);return (ai<0?999999:ai)-(bi<0?999999:bi)||a.name.localeCompare(b.name,'ja')})}
function setlistEditor(show){const ids=Array.isArray(show.setlistSongIds)?show.setlistSongIds:[];const songs=ids.map(id=>records.find(x=>x.id===id&&x.type==='songs')).filter(Boolean);return '<section class="section card"><h2>セットリスト管理</h2><p class="note">登録済み楽曲を選び、演奏順に並べ替えて保存します。従来の自由入力セットリストはそのまま残ります。</p><div id="setlistRows">'+(songs.length?songs.map((x,i)=>'<div class="item"><strong>#'+(i+1)+' '+esc(x.name)+'</strong></div>').join(''):'<p class="muted">まだ選択された楽曲はありません。</p>')+'</div><div class="field"><label>楽曲を追加</label><select id="addSetlistSong"><option value="">楽曲を選択</option>'+records.filter(x=>x.type==='songs').map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('')+'</select></div><div class="toolbar"><button type="button" class="secondary" id="addSetlistButton">＋ 追加</button><button type="button" class="primary" id="saveSetlistOrder">演奏順を保存</button></div><p class="note">同じ楽曲をアンコールなどで複数回登録できます。</p></section>'}
function trackEditor(release){const linked=linkedSongs(release),available=records.filter(r=>r.type==='songs'&&r.releaseId!==release.id);return '<section class="section card"><h2>収録曲・曲順管理</h2><p class="note">登録済みの楽曲を選択して追加できます。上下ボタンで曲順を変更し、「曲順を保存」を押してください。</p><div id="trackRows">'+(linked.length?linked.map((song,i)=>'<div class="item" data-track-id="'+esc(song.id)+'"><div><span class="pill">#'+(i+1)+'</span> <strong>'+esc(song.name)+'</strong></div><div class="toolbar"><button type="button" class="outline" data-move="-1" data-track="'+esc(song.id)+'">↑</button><button type="button" class="outline" data-move="1" data-track="'+esc(song.id)+'">↓</button><button type="button" class="outline danger" data-unlink="'+esc(song.id)+'">外す</button></div></div>').join(''):'<p class="muted">まだ収録曲はありません。</p>')+'</div><div class="field"><label>登録済み楽曲から追加</label><select id="addTrack"><option value="">楽曲を選択</option>'+available.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('')+'</select></div><div class="toolbar"><button type="button" class="secondary" id="addTrackButton">＋ 追加</button><button type="button" class="primary" id="saveTrackOrder">曲順を保存</button></div><p class="note">※作品から外した楽曲は削除されません。楽曲自体はアーカイブに残ります。</p></section>'}
function details(r){let blocks=[];if(r.type==='releases'){const songs=linkedSongs(r);blocks.push('<div class="section"><h2>関連する楽曲（'+songs.length+'曲）</h2>'+(songs.length?songs.map(x=>'<div class="item"><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.duration||'')+'</small></div><button class="outline" data-edit="'+esc(x.id)+'">編集</button></div>').join(''):'<p class="muted">関連する楽曲はありません。楽曲登録時にこの作品を選択してください。</p>')+'</div>')}
if(r.type==='songs'&&r.releaseId){const release=records.find(x=>x.id===r.releaseId&&x.type==='releases');if(release)blocks.push('<p class="pill">収録作品：'+esc(release.name)+'</p>')}
if(r.type==='shows'&&Array.isArray(r.setlistSongIds)&&r.setlistSongIds.length){const list=r.setlistSongIds.map(id=>records.find(x=>x.id===id&&x.type==='songs'));blocks.push('<section class="section"><h2>登録楽曲によるセットリスト</h2><ol>'+list.map(x=>'<li>'+esc(x?.name||'削除された楽曲')+'</li>').join('')+'</ol></section>')}
if(r.type==='shows'&&r.setlist)blocks.push('<div class="section"><h2>セットリスト</h2><ol>'+r.setlist.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></div>');
return blocks.join('')}
function home(){const band=records.find(r=>r.type==='bands');const recent=[...records].sort((a,b)=>(b.updated||'').localeCompare(a.updated||'')).slice(0,6);return `<div class="hero"><div class="eyebrow">${mode==='official'?'OFFICIAL WEBSITE':mode==='encyclopedia'?'BAND ENCYCLOPEDIA':'YOUR MUSIC HISTORY'}</div><h1>${esc(band?.name||'架空バンドの歴史を、ここに。')}</h1><p class="muted">${esc(band?.description||'結成から未来まで、楽曲・作品・ライブ・メンバーの記録をひとつにつなぐ。')}</p><div class="toolbar"><button class="primary" ${band?'data-edit="'+esc(band.id)+'"':'data-go="form" data-type="bands"'}>${band?'バンド情報を編集':'バンドを登録'}</button><button class="secondary" data-go="timeline">年表を見る</button></div></div><div class="grid">${[['members','メンバー'],['songs','楽曲'],['releases','作品'],['shows','ライブ']].map(([t,n])=>`<div class="card" data-card="${t}"><div class="eyebrow">${n}</div><div class="stat">${counts(t)}</div><span class="muted">登録件数</span><div class="toolbar"><button class="secondary" data-go="${t}">一覧を見る →</button></div></div>`).join('')}</div><section class="section"><h2>最近の更新</h2>${recent.length?recent.map(r=>`<div class="item"><div><strong>${esc(title(r))}</strong><small>${esc(TYPES[r.type])} ・ ${esc(date(r)||'日付未設定')}</small></div><button class="outline" data-edit="${esc(r.id)}">編集</button></div>`).join(''):'<div class="empty">まだ記録がありません。バンド情報を登録して始めましょう。</div>'}</section>`}
function timelineEntries(){const entries=[];for(const r of records){if(date(r))entries.push({r,when:date(r),label:r.type==='members'?'加入':r.type==='releases'?'発売':r.type==='shows'?'開催':TYPES[r.type]});if(r.type==='members'&&r.end)entries.push({r,when:r.end,label:'脱退',extra:true})}return entries.sort((a,b)=>a.when.localeCompare(b.when)||title(a.r).localeCompare(title(b.r),'ja'))}
function annualSummary(year){const rows=records.filter(r=>date(r).startsWith(year));const shows=rows.filter(r=>r.type==='shows');const releases=rows.filter(r=>r.type==='releases');const knownAttendance=shows.filter(r=>r.attendance!==''&&r.attendance!==null&&r.attendance!==undefined&&Number.isFinite(Number(r.attendance))&&Number(r.attendance)>=0);const knownRevenue=shows.map(showRevenue).filter(v=>v!==null&&Number.isFinite(v));const format=n=>new Intl.NumberFormat('ja-JP').format(n);const cards=[['発売作品',releases.length+'作品'],['ライブ',shows.length+'公演'],['総動員',knownAttendance.length?format(knownAttendance.reduce((n,r)=>n+Number(r.attendance),0))+'人':'未登録'],['興行収入',knownRevenue.length?format(knownRevenue.reduce((n,v)=>n+v,0))+'円':'未登録']];return '<div class="section card"><h2>'+esc(year)+'年の活動サマリー</h2><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">'+cards.map(([label,value])=>'<div style="padding:12px;border:1px solid rgba(190,160,90,.25);border-radius:10px"><small>'+esc(label)+'</small><strong style="display:block;font-size:1.15rem;overflow-wrap:anywhere">'+esc(value)+'</strong></div>').join('')+'</div><p class="note">登録済みデータから集計。動員数 '+knownAttendance.length+'/'+shows.length+'公演、収入 '+knownRevenue.length+'/'+shows.length+'公演分。未登録の公演は合計に含みません。</p></div>'}
function annualComparison(years){const metrics=[['shows','ライブ本数','公演'],['releases','発売作品数','作品'],['attendance','総動員数','人'],['revenue','興行収入','円']];const rows=years.slice().sort().map(year=>{const entries=records.filter(r=>date(r).startsWith(year)),shows=entries.filter(r=>r.type==='shows');const attendance=shows.filter(r=>r.attendance!==''&&r.attendance!==null&&r.attendance!==undefined&&Number.isFinite(Number(r.attendance))&&Number(r.attendance)>=0);const revenues=shows.map(showRevenue).filter(v=>v!==null&&Number.isFinite(v));return {year,shows:shows.length,releases:entries.filter(r=>r.type==='releases').length,attendance:attendance.length?attendance.reduce((n,r)=>n+Number(r.attendance),0):null,revenue:revenues.length?revenues.reduce((n,v)=>n+v,0):null,attendanceCoverage:attendance.length+'/'+shows.length,revenueCoverage:revenues.length+'/'+shows.length}});const max=Math.max(1,...rows.map(r=>r[timelineMetric]??0)),metric=metrics.find(m=>m[0]===timelineMetric)||metrics[0],fmt=n=>new Intl.NumberFormat('ja-JP').format(n);return '<section class="section card"><h2>年間活動比較グラフ</h2><label>比較する項目 <select id="timelineMetric">'+metrics.map(([k,label])=>'<option value="'+k+'" '+(timelineMetric===k?'selected':'')+'>'+label+'</option>').join('')+'</select></label><div style="display:grid;gap:12px;margin-top:16px">'+rows.map(r=>{const value=r[timelineMetric],missing=value===null,width=missing?0:Math.max(value>0?2:0,Math.round(value/max*100));return '<div><div style="display:flex;justify-content:space-between;gap:8px"><strong>'+esc(r.year)+'年</strong><span>'+(missing?'未登録':fmt(value)+metric[2])+'</span></div><div role="img" aria-label="'+esc(r.year)+'年 '+esc(metric[1])+' '+(missing?'未登録':fmt(value)+metric[2])+'" style="height:12px;background:rgba(190,160,90,.12);border-radius:8px;overflow:hidden;margin-top:5px"><div style="height:100%;width:'+width+'%;background:linear-gradient(90deg,#94702f,#d7b76b);border-radius:8px"></div></div>'+(timelineMetric==='attendance'||timelineMetric==='revenue'?'<small>集計対象 '+esc(r[timelineMetric+'Coverage'])+'公演</small>':'')+'</div>'}).join('')+'</div><p class="note">登録済みデータを年別比較。動員数・収入は未入力の公演を除外しています。</p></section>'}
function annualReportText(year){const entries=timelineEntries().filter(x=>x.when.startsWith(year));const rows=records.filter(r=>date(r).startsWith(year));const shows=rows.filter(r=>r.type==='shows'),releases=rows.filter(r=>r.type==='releases');const fmt=n=>new Intl.NumberFormat('ja-JP').format(n);const knownAttendance=shows.filter(r=>r.attendance!==''&&r.attendance!==null&&r.attendance!==undefined&&Number.isFinite(Number(r.attendance))&&Number(r.attendance)>=0);const knownRevenue=shows.map(showRevenue).filter(n=>n!==null&&Number.isFinite(n));const lines=['Band History Archive｜'+year+'年の活動レポート','',year+'年：作品 '+releases.length+'件／ライブ '+shows.length+'公演'];if(knownAttendance.length)lines.push('総動員：'+fmt(knownAttendance.reduce((n,r)=>n+Number(r.attendance),0))+'人（'+knownAttendance.length+'/'+shows.length+'公演）');if(knownRevenue.length)lines.push('興行収入：'+fmt(knownRevenue.reduce((n,v)=>n+v,0))+'円（'+knownRevenue.length+'/'+shows.length+'公演）');lines.push('','【活動記録】');for(const x of entries)lines.push(x.when+'｜'+x.label+'｜'+title(x.r));lines.push('','※登録済みデータから作成。未登録の動員数・収入は含みません。');return lines.join('\n')}
function saveAnnualReport(year){const blob=new Blob(['\ufeff'+annualReportText(year)],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='band-history-'+year+'-report.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function shareAnnualReport(year){const content=annualReportText(year);try{if(navigator.share){await navigator.share({title:year+'年の活動レポート',text:content});return}if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(content);toast('レポートをコピーしました');return}toast('共有非対応のため「テキスト保存」をお使いください')}catch(e){if(e.name!=='AbortError')toast('共有できませんでした。テキスト保存をお試しください')}}
function printAnnualReport(){const report=$('annualReport');if(!report)return;const win=window.open('','_blank');if(!win){toast('ポップアップがブロックされました。Safariで開いて再試行してください');return}const clone=report.cloneNode(true);clone.querySelectorAll('button,.toolbar').forEach(el=>el.remove());const safe=clone.outerHTML;win.document.open();win.document.write('<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>年間活動レポート</title><style>@page{size:A4;margin:18mm}body{font-family:-apple-system,BlinkMacSystemFont,"Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;color:#222;background:#fff;line-height:1.7;font-size:11pt}h2{font-size:22pt;border-bottom:2px solid #9a7739;padding-bottom:8px}h3{margin-top:20px}ol{padding-left:22px}li{break-inside:avoid;margin-bottom:5px}.note{font-size:9pt;color:#555}button{display:none}section{max-width:850px;margin:auto}@media screen{body{padding:20px} .print-tip{padding:12px;background:#f4ead9;border-radius:8px;margin-bottom:20px}}@media print{.print-tip{display:none}}</style></head><body><div class="print-tip">iPhoneでは共有メニューから「プリント」を選び、プレビューを拡大して共有するとPDFとして保存できます。<br><button style="display:inline-block;padding:10px;margin-top:8px" onclick="window.print()">印刷・PDF保存</button></div>'+safe+'</body></html>');win.document.close();win.focus()}
function annualReport(year){if(!year)return '';const entries=timelineEntries().filter(x=>x.when.startsWith(year));const rows=records.filter(r=>date(r).startsWith(year));const releases=rows.filter(r=>r.type==='releases'),shows=rows.filter(r=>r.type==='shows');const joins=entries.filter(x=>x.r.type==='members'&&!x.extra),leaves=entries.filter(x=>x.r.type==='members'&&x.extra),events=rows.filter(r=>r.type==='events');const validShows=shows.filter(r=>r.attendance!==''&&r.attendance!==null&&r.attendance!==undefined&&Number.isFinite(Number(r.attendance))&&Number(r.attendance)>=0);const revenue=shows.map(showRevenue).filter(x=>x!==null&&Number.isFinite(x));const fmt=n=>new Intl.NumberFormat('ja-JP').format(n);const names=arr=>arr.slice(0,8).map(r=>esc(title(r))).join('、')+(arr.length>8?' ほか'+(arr.length-8)+'件':'');const blocks=['<p>'+esc(year)+'年は、'+releases.length+'作品の発売と'+shows.length+'公演のライブが登録されています。</p>'];if(releases.length)blocks.push('<p><strong>作品：</strong>'+names(releases)+'</p>');if(shows.length)blocks.push('<p><strong>ライブ：</strong>'+names(shows)+'</p>');if(validShows.length)blocks.push('<p><strong>動員数：</strong>'+fmt(validShows.reduce((n,r)=>n+Number(r.attendance),0))+'人（'+validShows.length+'/'+shows.length+'公演分）</p>');if(revenue.length)blocks.push('<p><strong>興行収入：</strong>'+fmt(revenue.reduce((n,v)=>n+v,0))+'円（'+revenue.length+'/'+shows.length+'公演分）</p>');if(joins.length)blocks.push('<p><strong>加入：</strong>'+names(joins.map(x=>x.r))+'</p>');if(leaves.length)blocks.push('<p><strong>脱退：</strong>'+names(leaves.map(x=>x.r))+'</p>');if(events.length)blocks.push('<p><strong>主な出来事：</strong>'+names(events)+'</p>');const chronology=entries.map(x=>'<li><strong>'+esc(x.when)+'</strong>　'+esc(x.label)+'：'+esc(title(x.r))+'</li>').join('');return '<section class="section card" id="annualReport"><h2>'+esc(year)+'年の活動レポート</h2><div class="toolbar"><button type="button" class="secondary" id="saveAnnualReport">テキスト保存</button><button type="button" class="outline" id="shareAnnualReport">共有する</button><button type="button" class="outline" id="printAnnualReport">印刷・PDF保存</button></div><div style="line-height:1.8">'+blocks.join('')+'</div><h3>活動の記録</h3>'+(chronology?'<ol style="padding-left:22px;line-height:1.8">'+chronology+'</ol>':'<p class="muted">記録はありません。</p>')+'<p class="note">登録された情報のみから作成しています。動員・収入の未登録分は含まれません。</p></section>'}
function timeline(){const all=timelineEntries();const years=[...new Set(all.map(x=>x.when.slice(0,4)).filter(x=>/^\d{4}$/.test(x)))].sort().reverse();const types=[['all','すべて'],['releases','作品'],['shows','ライブ'],['members','メンバー'],['songs','楽曲'],['events','出来事'],['bands','バンド']];const items=all.filter(x=>(!timelineYear||x.when.startsWith(timelineYear))&&(timelineType==='all'||x.r.type===timelineType));const groups=new Map();for(const x of items){const year=x.when.slice(0,4)||'年不明';if(!groups.has(year))groups.set(year,[]);groups.get(year).push(x)}return '<div class="eyebrow">CHRONOLOGY</div><h1>バンド年表</h1><p class="muted">作品発売・ライブ・加入と脱退・出来事を時系列で表示します。</p><div class="toolbar"><button class="primary" data-go="form" data-type="events">＋ 出来事を追加</button><button class="secondary" data-go="form" data-type="shows">＋ ライブを追加</button></div><div class="toolbar"><label>年 <select id="timelineYear"><option value="">すべての年</option>'+years.map(y=>'<option value="'+y+'" '+(timelineYear===y?'selected':'')+'>'+y+'年</option>').join('')+'</select></label><label>種類 <select id="timelineType">'+types.map(([k,v])=>'<option value="'+k+'" '+(timelineType===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label><button type="button" class="outline" id="clearTimeline">条件を解除</button></div><p class="note">'+items.length+' / '+all.length+' 件</p>'+(years.length?'<section class="section card"><h2>年間活動レポート</h2><label>レポートの年 <select id="reportYear">'+years.map(y=>'<option value="'+y+'" '+((reportYear||years[0])===y?'selected':'')+'>'+y+'年</option>').join('')+'</select></label></section>'+annualReport(years.includes(reportYear)?reportYear:years[0]):'')+annualComparison(years)+(timelineYear?annualSummary(timelineYear):years.map(y=>annualSummary(y)).join(''))+(items.length?'<div class="timeline">'+[...groups].map(([year,group])=>'<section class="section"><h2>'+esc(year)+'年 <small>('+group.length+'件)</small></h2>'+group.map(x=>{const img=featuredPhoto(x.r)||(x.r.type==='releases'&&/^https:\/\//i.test(x.r.coverUrl||'')?x.r.coverUrl:'');const art=img&&/^(https:\/\/|data:image\/jpeg;base64,)/i.test(img)?'<img src="'+esc(img)+'" alt="'+esc(title(x.r))+'の代表画像" loading="lazy" style="width:72px;height:72px;flex-shrink:0;object-fit:cover;border-radius:10px;border:1px solid rgba(190,160,90,.35)" onerror="this.style.display=\'none\'">':'<div aria-hidden="true" style="width:72px;height:72px;flex-shrink:0;display:grid;place-items:center;border-radius:10px;background:rgba(190,160,90,.1);font-size:26px">♫</div>';return '<div class="item" style="gap:12px;align-items:center">'+art+'<div style="min-width:0;flex:1"><div class="date">'+esc(x.when)+' · '+esc(x.label)+'</div><strong>'+esc(title(x.r))+'</strong><small>'+esc((x.r.description||x.r.venue||'').slice(0,90))+'</small></div><button class="outline" data-detail="'+esc(x.r.id)+'">詳細を見る</button></div>'}).join('')+'</section>').join('')+'</div>':'<div class="empty">条件に一致する記録がありません。</div>')}
function archiveFiltered(type){return records.filter(r=>r.type===type&&[r.name,r.description,r.genre,r.venue,r.kind,r.role,r.tour].some(v=>String(v||'').toLowerCase().includes(filter.toLowerCase()))&&(!archiveYear||date(r).startsWith(archiveYear))&&(!archiveFacet||String(r[type==='releases'?'kind':type==='shows'?'tour':type==='members'?'role':'genre']||'')===archiveFacet)).sort((a,b)=>{const [key,dir]=archiveSort.split('-');const multiplier=dir==='asc'?1:-1;let x=0;if(key==='name')x=title(a).localeCompare(title(b),'ja');else if(key==='date')x=date(a).localeCompare(date(b));else{const numeric=r=>key==='revenue'?showRevenue(r):r[key];const av=numeric(a),bv=numeric(b);const an=av!==''&&av!==null&&av!==undefined&&Number.isFinite(Number(av))?Number(av):null,bn=bv!==''&&bv!==null&&bv!==undefined&&Number.isFinite(Number(bv))?Number(bv):null;if(an===null&&bn!==null)return 1;if(bn===null&&an!==null)return -1;if(an!==null&&bn!==null)x=an-bn}return multiplier*x||date(b).localeCompare(date(a))})}
function listPage(type){const rows=records.filter(r=>r.type===type);const years=[...new Set(rows.map(r=>date(r).slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse();const facetKey=type==='releases'?'kind':type==='shows'?'tour':type==='members'?'role':'genre';const facets=[...new Set(rows.map(r=>String(r[facetKey]||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja'));const sortOptions=[['date-desc','日付：新しい順'],['date-asc','日付：古い順'],['name-asc','名前：あいうえお順'],['name-desc','名前：逆順'],...(type==='releases'?[['sales-desc','売上枚数：多い順'],['sales-asc','売上枚数：少ない順']]:[]),...(type==='shows'?[['attendance-desc','動員数：多い順'],['attendance-asc','動員数：少ない順'],['revenue-desc','興行収入：多い順'],['revenue-asc','興行収入：少ない順']]:[])];const facetName=type==='releases'?'作品形態':type==='shows'?'ツアー':type==='members'?'担当パート':'ジャンル';const options=(values,selected)=>values.map(v=>'<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(v)+'</option>').join('');return '<div class="eyebrow">ARCHIVE / '+esc(type.toUpperCase())+'</div><h1>'+esc(TYPES[type])+'アーカイブ</h1><div class="toolbar"><button class="primary" data-go="form" data-type="'+esc(type)+'">＋ 新規登録</button></div><input id="filter" class="search" placeholder="この一覧を検索" value="'+esc(filter)+'" aria-label="一覧検索"><div class="toolbar"><label>年 <select id="archiveYear"><option value="">すべての年</option>'+options(years,archiveYear)+'</select></label><label>'+esc(facetName)+' <select id="archiveFacet"><option value="">すべて</option>'+options(facets,archiveFacet)+'</select></label><label>並べ替え <select id="archiveSort">'+sortOptions.map(([v,label])=>'<option value="'+v+'" '+(archiveSort===v?'selected':'')+'>'+label+'</option>').join('')+'</select></label><button type="button" class="outline" id="clearArchiveFilters">条件を解除</button></div><div class="toolbar" role="group" aria-label="一覧の表示形式"><button type="button" class="'+(archiveLayout==='list'?'primary':'outline')+'" data-layout="list" aria-pressed="'+(archiveLayout==='list')+'">☰ リスト</button><button type="button" class="'+(archiveLayout==='grid'?'primary':'outline')+'" data-layout="grid" aria-pressed="'+(archiveLayout==='grid')+'">▦ グリッド</button></div><p id="archiveCount" class="note">'+archiveFiltered(type).length+' / '+rows.length+' 件</p><div id="listResults">'+listItems(archiveFiltered(type))+'</div>'}
function gridItems(arr){if(!arr.length)return '<div class="empty">該当するデータがありません。</div>';return '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px">'+arr.map(r=>{const photo=featuredPhoto(r)||(r.type==='releases'&&/^https:\/\//i.test(r.coverUrl||'')?r.coverUrl:'');const art=photo&&/^(https:\/\/|data:image\/jpeg;base64,)/i.test(photo)?'<img src="'+esc(photo)+'" alt="'+esc(title(r))+'の画像" loading="lazy" style="display:block;width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px 10px 0 0" onerror="this.style.display=\'none\'">':'<div aria-hidden="true" style="aspect-ratio:1;display:grid;place-items:center;font-size:46px;background:rgba(190,160,90,.1)">♫</div>';return '<button type="button" data-detail="'+esc(r.id)+'" style="text-align:left;min-width:0;padding:0;border:1px solid rgba(190,160,90,.3);border-radius:12px;overflow:hidden;background:transparent;color:inherit;cursor:pointer">'+art+'<div style="padding:10px"><strong style="display:block;overflow-wrap:anywhere">'+esc(title(r))+'</strong><small>'+esc(date(r)||'日付未設定')+'</small></div></button>'}).join('')+'</div>'}
function listItems(arr){if(archiveLayout==='grid')return gridItems(arr);return arr.length?arr.map(r=>{const release=r.type==='songs'&&r.releaseId?records.find(x=>x.type==='releases'&&x.id===r.releaseId):null;const related=r.type==='releases'?linkedSongs(r):[];const image=featuredPhoto(r)||(r.type==='releases'&&/^https:\/\//i.test(r.coverUrl||'')?r.coverUrl:'');const thumb=image&&/^(https:\/\/|data:image\/jpeg;base64,)/i.test(image)?`<img src="${esc(image)}" alt="${esc(title(r))}の画像" loading="lazy" style="width:76px;height:76px;object-fit:cover;border-radius:10px;flex-shrink:0;border:1px solid rgba(190,160,90,.35)" onerror="this.style.display='none'">`:`<div aria-hidden="true" style="width:76px;height:76px;flex-shrink:0;display:grid;place-items:center;border-radius:10px;background:rgba(190,160,90,.1);font-size:26px">${r.type==='releases'?'♫':r.type==='shows'?'♬':'♪'}</div>`;return `<div class="item" style="align-items:center;gap:12px">${thumb}<div style="min-width:0;flex:1"><strong>${esc(title(r))}</strong><small>${esc(date(r)||'日付未設定')} ${r.kind?'・'+esc(r.kind):''}</small>${r.type==='songs'?'<div class="pill">収録作品：'+esc(release?.name||(r.releaseId?'作品が見つかりません':'未設定'))+'</div>':''}${r.type==='releases'?'<div class="pill">関連楽曲：'+related.length+'曲</div>'+ (related.length?'<p class="muted">'+related.map(x=>esc(x.name)).join(' / ')+'</p>':''):''}<p class="muted">${esc((r.description||r.role||r.venue||'').slice(0,120))}</p></div><button class="outline" data-detail="${esc(r.id)}">詳細を見る</button></div>`}).join(''):'<div class="empty">該当するデータがありません。</div>'}
function localPhotoEditor(r){const photos=Array.isArray(r.localPhotos)?r.localPhotos:[];const urls=String(r.photoUrls||'').split(/\r?\n/).map(x=>x.trim()).filter(x=>/^https:\/\//i.test(x));const current=Number.isInteger(r.featuredPhotoIndex)?r.featuredPhotoIndex:-1;const choices=[...urls,...photos];return '<section class="section card"><h2>写真と代表画像</h2><p class="note">写真を選ぶと縮小して端末内に保存します（最大8枚）。代表画像は下の写真から設定できます。</p><input id="localPhotoInput" type="file" accept="image/*" multiple aria-label="写真を選択"><div id="localPhotoStatus" class="note"></div>'+choices.map((p,i)=>'<div class="item"><img src="'+esc(p)+'" alt="写真'+(i+1)+'" style="width:64px;height:64px;object-fit:cover;border-radius:8px"><div><button type="button" class="outline" data-featured-photo="'+i+'" '+(current===i?'disabled':'')+'>'+(current===i?'★ 代表画像':'代表画像にする')+'</button>'+(i>=urls.length?'<button type="button" class="outline danger" data-remove-photo="'+(i-urls.length)+'">削除</button>':'')+'</div></div>').join('')+(current>=0?'<button type="button" class="outline" data-clear-featured>代表画像を解除</button>':'')+'<p class="note">代表画像は保存済みの写真から選択。JSONバックアップに写真も含まれます。</p></section>'}
function compressPhoto(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(Error('画像ファイルを選んでください'));if(file.size>15*1024*1024)return reject(Error('15MB以下の画像を選んでください'));const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);try{const scale=Math.min(1,1200/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/jpeg',0.72);if(result.length>950000)throw Error('圧縮後も大きすぎる画像です');resolve(result)}catch(e){reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('画像を読み込めませんでした'))};img.src=url})}
function featuredPhoto(r){const urls=[...String(r.photoUrls||'').split(/\r?\n/).map(x=>x.trim()).filter(x=>/^https:\/\//i.test(x)),...(Array.isArray(r.localPhotos)?r.localPhotos:[])];return Number.isInteger(r.featuredPhotoIndex)?urls[r.featuredPhotoIndex]||'':''}
function galleryFor(r){const urls=[...String(r.photoUrls||'').split(/\r?\n/).map(x=>x.trim()).filter(x=>/^https:\/\//i.test(x)),...(Array.isArray(r.localPhotos)?r.localPhotos.filter(x=>/^data:image\/jpeg;base64,/.test(x)):[])].slice(0,40);if(!urls.length)return '';return '<section class="section card"><h2>フォトギャラリー（'+urls.length+'枚）</h2><div class="grid">'+urls.map((url,i)=>'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer" aria-label="写真'+(i+1)+'を開く"><img src="'+esc(url)+'" alt="'+esc(r.name)+' 写真'+(i+1)+'" loading="lazy" style="display:block;width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:10px;border:1px solid var(--line)" onerror="this.parentElement.style.display=\'none\'"></a>').join('')+'</div><p class="note">写真をタップすると元画像を開きます。HTTPS画像URLと端末内に保存した写真に対応。</p></section>'}
function recordDetail(){const r=records.find(x=>x.id===editId);if(!r)return '<div class="empty">記録が見つかりません。</div>';const fields=SCHEMAS[r.type].filter(([key,,kind])=>kind!=='textarea'&&kind!=='calculated'&&key!=='coverUrl'&&key!=='mvUrl'&&r[key]!==''&&r[key]!==undefined&&r[key]!==null).map(([key,label])=>{let value=r[key];if(key==='releaseId')value=records.find(x=>x.id===value)?.name||'作品が見つかりません';return '<div class="item"><span class="muted">'+esc(label)+'</span><strong>'+esc(value)+'</strong></div>'}).join('');const url=featuredPhoto(r)||(r.type==='releases'?r.coverUrl:null);const cover=url&&(/^(https:\/\/|data:image\/jpeg;base64,)/i.test(url))?'<img src="'+esc(url)+'" alt="'+esc(r.name)+'の代表画像" loading="lazy" style="display:block;width:min(100%,420px);height:auto;aspect-ratio:4/3;object-fit:cover;border-radius:12px;border:1px solid var(--line);margin:14px 0" onerror="this.style.display=\'none\'">':'';const textBlocks=[['紹介・概要',r.description],['歌詞',r.lyrics],['収録曲メモ',r.tracklist],['経歴・ソロ活動',r.solo]].filter(([,v])=>String(v||'').trim()).map(([name,v])=>'<section class="section card"><h2>'+esc(name)+'</h2><p style="white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8">'+esc(v)+'</p></section>').join('');const links=[['MVを見る',r.mvUrl],['参照元を開く',r.sourceUrl]].filter(([,v])=>/^https?:\/\//i.test(String(v||''))).map(([name,v])=>'<a class="secondary" href="'+esc(v)+'" target="_blank" rel="noopener noreferrer">'+esc(name)+' ↗</a>').join('');const related=details(r);const revenue=r.type==='shows'&&showRevenue(r)!==null?'<section class="section card"><h2>興行収入（概算）</h2><div class="stat">'+new Intl.NumberFormat('ja-JP').format(showRevenue(r))+' 円</div><p class="note">チケット価格と販売枚数、または動員数から算出</p></section>':'';return '<div class="eyebrow">ARCHIVE / '+esc(TYPES[r.type])+'</div><h1>'+esc(r.name)+'</h1><p class="muted">'+esc(date(r)||'日付未設定')+'</p>'+cover+'<div class="toolbar"><button class="primary" data-edit="'+esc(r.id)+'">編集する</button><button class="secondary" data-go="'+esc(r.type)+'">一覧に戻る</button>'+links+'</div><section class="section card"><h2>基本情報</h2>'+(fields||'<p class="muted">詳細情報は未登録です。</p>')+'</section>'+galleryFor(r)+revenue+textBlocks+related}
function validMoney(v){return v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Number(v)>=0}
function parseTicketTiers(text){if(!String(text||'').trim())return [];return String(text).split(/\r?\n/).filter(x=>x.trim()).map(line=>{const parts=line.split(/[,，、\t]/).map(x=>x.trim());return {name:parts[0]||'',price:parts[1],quantity:parts[2],valid:parts.length===3&&Boolean(parts[0])&&validMoney(parts[1])&&validMoney(parts[2])&&Number.isInteger(Number(parts[2]))}})}
function ticketTierState(r){const tiers=parseTicketTiers(r.ticketTiers);if(!tiers.length)return {active:false,valid:true,tiers:[],quantity:0,revenue:0};const valid=tiers.every(x=>x.valid);return {active:true,valid,tiers,quantity:valid?tiers.reduce((n,x)=>n+Number(x.quantity),0):0,revenue:valid?tiers.reduce((n,x)=>n+Number(x.price)*Number(x.quantity),0):0}}
function showRevenue(r){const t=ticketTierState(r);return t.active?(t.valid?t.revenue:null):(validMoney(r.attendance)&&validMoney(r.ticketPrice)?Number(r.attendance)*Number(r.ticketPrice):null)}
function statistics(){const songs=records.filter(r=>r.type==='songs'),releases=records.filter(r=>r.type==='releases'),shows=records.filter(r=>r.type==='shows');const valid=r=>r!==''&&r!==null&&r!==undefined&&Number.isFinite(Number(r))&&Number(r)>=0;const sum=(rows,key)=>rows.reduce((total,r)=>total+(valid(r[key])?Number(r[key]):0),0);const format=n=>new Intl.NumberFormat('ja-JP').format(n);const countFilled=(rows,key)=>rows.filter(r=>valid(r[key])).length;const cards=[['楽曲数',songs.length,'曲'],['作品数',releases.length,'作品'],['ライブ本数',shows.length,'公演'],['作品売上枚数',sum(releases,'sales'),'枚'],['ライブ総動員',sum(shows,'attendance'),'人'],['ライブ興行収入',shows.reduce((total,r)=>total+(showRevenue(r)??0),0),'円']];const years=new Map();for(const r of [...releases,...shows]){const d=String(r.date||'');if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(d))continue;const y=d.slice(0,4),row=years.get(y)||{year:y,releases:0,shows:0};if(r.type==='releases')row.releases++;else row.shows++;years.set(y,row)}const data=[...years.values()].sort((a,b)=>a.year.localeCompare(b.year));const max=Math.max(1,...data.map(x=>Math.max(x.releases,x.shows)));return '<div class="eyebrow">ARCHIVE ANALYTICS</div><h1>活動統計</h1><p class="muted">登録済みの記録から自動集計しています。未入力の売上・動員数は0として合計しますが、入力済み件数も併記します。</p><div class="grid">'+cards.map(([name,n,unit])=>'<div class="card"><div class="eyebrow">'+name+'</div><div class="stat">'+format(n)+'<small style="font-size:14px;margin-left:5px">'+unit+'</small></div></div>').join('')+'</div><section class="section card"><h2>数値データの入力状況</h2><p>売上枚数：'+countFilled(releases,'sales')+' / '+releases.length+'作品</p><p>動員数：'+countFilled(shows,'attendance')+' / '+shows.length+'公演</p><p>興行収入：'+shows.filter(r=>showRevenue(r)!==null).length+' / '+shows.length+'公演</p></section><section class="section card"><h2>年別活動件数</h2>'+(data.length?data.map(x=>'<div style="margin:16px 0"><strong>'+esc(x.year)+'年</strong><div style="margin-top:7px">作品 '+x.releases+'件<div style="height:9px;background:#453526;border-radius:8px"><div style="height:9px;width:'+Math.round(x.releases/max*100)+'%;background:#d4ad72;border-radius:8px"></div></div></div><div style="margin-top:7px">ライブ '+x.shows+'件<div style="height:9px;background:#453526;border-radius:8px"><div style="height:9px;width:'+Math.round(x.shows/max*100)+'%;background:#ad7767;border-radius:8px"></div></div></div></div>').join(''):'<p class="muted">作品やライブの日付を登録すると年別グラフが表示されます。</p>')+'</section><p class="note">売上枚数・動員数・興行収入は席種別チケットの販売枚数 × 価格を優先し、席種未設定時は動員数 × 一律価格で概算します。招待客・手数料などは反映しません。</p>'}
function more(){return `<div class="eyebrow">EXPLORE</div><h1>その他の機能</h1><div class="grid">${[['bands','バンド情報'],['members','メンバー'],['shows','ライブ'],['events','出来事'],['search','全体検索'],['statistics','活動統計'],['settings','設定・バックアップ']].map(([v,n])=>`<div class="card"><h3>${n}</h3><button class="secondary" data-go="${v}">開く →</button></div>`).join('')}</div><section class="section"><div class="card"><h3>開発状況</h3><p>第1段階：基本データ登録・年表・検索・端末内保存・JSONバックアップを実装。</p><p>高度なシミュレーション、画像管理、複数世界線、Excel/PDF出力などは今後追加します。</p></div></section>`}
function formPage(){const type=window.formType||'bands',r=records.find(x=>x.id===editId)||{type};return `<div class="eyebrow">${editId?'EDIT RECORD':'NEW RECORD'}</div><h1>${esc(TYPES[type])}${editId?'を編集':'を登録'}</h1><form id="recordForm" class="form" data-type="${type}">${SCHEMAS[type].map(([key,label,kind,required])=>{let input='';if(kind==='calculated')input=`<input type="text" name="${key}" value="${type==='shows'&&showRevenue(r)!==null?esc(new Intl.NumberFormat('ja-JP').format(showRevenue(r))+' 円'):'未計算（動員数・チケット価格を入力）'}" readonly aria-label="${esc(label)}"><p class="note">動員数 × チケット価格で自動計算します。実際の収支や手数料は含みません。</p>`;else if(kind==='textarea')input=`<textarea name="${key}" ${required?'required':''}>${esc(r[key])}</textarea>`;else if(kind.startsWith('ref:')){const target=kind.slice(4);const choices=records.filter(x=>x.type===target);input=`<select name="${key}" aria-label="${esc(label)}"><option value="">未設定</option>${choices.map(x=>`<option value="${esc(x.id)}" ${r[key]===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${!choices.length?'<p class="note">作品がまだありません。先に「作品」からアルバム・シングルを登録してください。</p>':''}`}else input=`<input type="${kind}" name="${key}" value="${esc(r[key])}" ${required?'required':''}>`;return `<div class="field"><label>${esc(label)}${required?' *':''}</label>${input}</div>`}).join('')}<div class="toolbar"><button class="primary" type="submit">保存する</button><button class="secondary" type="button" data-go="${type}">キャンセル</button>${editId?'<button class="outline danger" type="button" id="deleteRecord">削除</button>':''}</div></form>${type==='shows'?'<p class="note">席種別チケット例：VIP,15000,100（改行して一般,8000,400）。区分を入力すると一律価格より優先して計算します。販売枚数と動員数は別の値です。</p>':''}${editId?details(r):''}${editId&&type==='releases'?trackEditor(r):''}${editId&&type==='shows'?setlistEditor(r):''}${editId?localPhotoEditor(r):''}<p class="note">データはこのブラウザの端末内に保存されます。定期的にJSONバックアップを作成してください。</p>`}
function searchPage(){return `<div class="eyebrow">GLOBAL SEARCH</div><h1>全体検索</h1><input id="globalSearch" class="search" placeholder="曲名、人物名、会場名など" aria-label="全体検索"><div id="searchResults">${listItems(records.slice(0,30))}</div>`}
function settings(){return `<div class="eyebrow">PREFERENCES & DATA</div><h1>設定・データ管理</h1><div class="card"><h3>データのバックアップ</h3><p>全${records.length}件の登録データをJSONファイルに保存できます。</p><div class="toolbar"><button class="primary" id="exportJson">JSONを書き出す</button><label class="secondary" for="importJson" style="cursor:pointer">JSONを読み込む</label><input type="file" id="importJson" accept=".json,application/json" hidden></div><p class="note">読み込み時は現在のデータを置き換えます。確認画面が表示されます。</p></div><div class="card section"><h3>保存場所</h3><p>このブラウザのIndexedDBに保存しています。ブラウザデータの削除や端末の故障で消える可能性があります。</p><p class="note">アプリはオンライン接続を前提としています。ホーム画面への追加はブラウザの共有メニューから行えます。</p></div><div class="card section"><h3>アプリ情報</h3><p>Band History Archive · Prototype 0.4.6</p><p class="note">データ形式 v1 / GitHub Pages対応 / 外部サーバーへのデータ送信なし</p></div>`}
function updateArchiveResults(){if(!TYPES[view])return;const rows=archiveFiltered(view);$('listResults').innerHTML=listItems(rows);const count=$('archiveCount');if(count)count.textContent=rows.length+' / '+records.filter(r=>r.type===view).length+' 件';attachResultButtons()}
function yearsForReport(){const years=[...new Set(timelineEntries().map(x=>x.when.slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse();return years.includes(reportYear)?reportYear:years[0]}
function attach(){const pr=$('printAnnualReport');if(pr)pr.onclick=printAnnualReport;const sy=$('saveAnnualReport'),sh=$('shareAnnualReport');if(sy)sy.onclick=()=>saveAnnualReport(yearsForReport());if(sh)sh.onclick=()=>shareAnnualReport(yearsForReport());const ry=$('reportYear');if(ry)ry.onchange=()=>{reportYear=ry.value;render()};const tm=$('timelineMetric');if(tm)tm.onchange=()=>{timelineMetric=tm.value;render()};const ty=$('timelineYear'),tt=$('timelineType'),tc=$('clearTimeline');if(ty)ty.onchange=()=>{timelineYear=ty.value;render()};if(tt)tt.onchange=()=>{timelineType=tt.value;render()};if(tc)tc.onclick=()=>{timelineYear='';timelineType='all';render()};const yr=$('archiveYear'),facet=$('archiveFacet'),sort=$('archiveSort'),clear=$('clearArchiveFilters');if(sort)sort.onchange=()=>{archiveSort=sort.value;updateArchiveResults()};if(yr)yr.onchange=()=>{archiveYear=yr.value;updateArchiveResults()};if(facet)facet.onchange=()=>{archiveFacet=facet.value;updateArchiveResults()};if(clear)clear.onclick=()=>{filter='';archiveYear='';archiveFacet='';archiveSort='date-desc';render()};document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{archiveLayout=b.dataset.layout==='grid'?'grid':'list';try{localStorage.setItem('band-archive-layout',archiveLayout)}catch(e){}render()});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{editId=b.dataset.detail;view='detail';render();window.scrollTo(0,0)});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(b.dataset.go==='form'){window.formType=b.dataset.type;editId=null}nav(b.dataset.go)});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const r=records.find(x=>x.id===b.dataset.edit);if(r){editId=r.id;window.formType=r.type;view='form';render()}});const photoInput=$('localPhotoInput');if(photoInput){const recordId=editId;photoInput.onchange=async()=>{const files=[...photoInput.files];const status=$('localPhotoStatus');const current=records.find(x=>x.id===recordId);if(!current)return;const photos=Array.isArray(current.localPhotos)?[...current.localPhotos]:[];if(photos.length+files.length>8){status.textContent='最大8枚までです。';return}photoInput.disabled=true;status.textContent='画像を圧縮・保存しています…';try{for(const file of files)photos.push(await compressPhoto(file));await txn('readwrite',store=>store.put({...current,localPhotos:photos,updated:new Date().toISOString()}));status.textContent='写真を保存しました';await refresh()}catch(e){status.textContent='保存できませんでした：'+e.message;photoInput.disabled=false}};document.querySelectorAll('[data-featured-photo]').forEach(b=>b.onclick=async()=>{const current=records.find(x=>x.id===recordId);if(!current)return;try{await txn('readwrite',store=>store.put({...current,featuredPhotoIndex:Number(b.dataset.featuredPhoto),updated:new Date().toISOString()}));toast('代表画像を設定しました');await refresh()}catch(e){toast('設定に失敗しました: '+e.message)}});const clearFeatured=document.querySelector('[data-clear-featured]');if(clearFeatured)clearFeatured.onclick=async()=>{const current=records.find(x=>x.id===recordId);if(!current)return;try{await txn('readwrite',store=>store.put({...current,featuredPhotoIndex:-1,updated:new Date().toISOString()}));await refresh()}catch(e){toast('解除に失敗しました: '+e.message)}};document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=async()=>{if(!confirm('この写真を削除しますか？'))return;const current=records.find(x=>x.id===recordId);if(!current)return;const photos=[...(current.localPhotos||[])];const deletedIndex=Number(b.dataset.removePhoto);const urlCount=String(current.photoUrls||'').split(/\r?\n/).filter(x=>/^https:\/\//i.test(x.trim())).length;const deletedGlobal=urlCount+deletedIndex;photos.splice(deletedIndex,1);const featuredPhotoIndex=current.featuredPhotoIndex===deletedGlobal?-1:(Number.isInteger(current.featuredPhotoIndex)&&current.featuredPhotoIndex>deletedGlobal?current.featuredPhotoIndex-1:current.featuredPhotoIndex);try{await txn('readwrite',store=>store.put({...current,localPhotos:photos,featuredPhotoIndex,updated:new Date().toISOString()}));toast('写真を削除しました');await refresh()}catch(e){toast('削除に失敗しました: '+e.message)}})};const f=$('recordForm');if(f)f.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f));const old=records.find(x=>x.id===editId);if(f.dataset.type==='shows'){const tiers=ticketTierState(data);if(tiers.active&&!tiers.valid){alert('席種別チケットの入力形式を確認してください。\n例：VIP,15000,100\n一般,8000,400\n学生,5000,100');return}data.revenue=showRevenue(data)===null?'':String(showRevenue(data));}const obj={...(old||{}),...data,id:editId||crypto.randomUUID(),type:f.dataset.type,updated:new Date().toISOString(),schemaVersion:VERSION};try{await txn('readwrite',s=>s.put(obj));toast('保存しました');editId=null;view=obj.type;await refresh()}catch(e){toast('保存に失敗しました: '+e.message)}};if(f&&f.dataset.type==='shows'){const updateRevenue=()=>{const output=f.elements.namedItem('revenue');if(!output)return;const data={attendance:f.elements.namedItem('attendance').value,ticketPrice:f.elements.namedItem('ticketPrice').value,ticketTiers:f.elements.namedItem('ticketTiers').value};const tier=ticketTierState(data),amount=showRevenue(data);output.value=tier.active&&!tier.valid?'席種別チケットの形式を確認':amount===null?'未計算（人数・価格を入力）':new Intl.NumberFormat('ja-JP').format(amount)+' 円'+(tier.active?'（販売 '+tier.quantity+'枚）':'');};['attendance','ticketPrice','ticketTiers'].forEach(k=>f.elements.namedItem(k).addEventListener('input',updateRevenue));updateRevenue()}const trackRows=$('trackRows');if(trackRows){let trackIds=linkedSongs(records.find(x=>x.id===editId)).map(x=>x.id);const releaseId=editId;const paint=()=>{const list=trackIds.map(id=>records.find(x=>x.id===id)).filter(Boolean);trackRows.innerHTML=list.length?list.map((x,i)=>'<div class="item"><div><span class="pill">#'+(i+1)+'</span> <strong>'+esc(x.name)+'</strong></div><div class="toolbar"><button type="button" class="outline" data-move="-1" data-track="'+esc(x.id)+'">↑</button><button type="button" class="outline" data-move="1" data-track="'+esc(x.id)+'">↓</button><button type="button" class="outline danger" data-unlink="'+esc(x.id)+'">外す</button></div></div>').join(''):'<p class="muted">まだ収録曲はありません。</p>';trackRows.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=trackIds.indexOf(b.dataset.track),j=i+Number(b.dataset.move);if(j>=0&&j<trackIds.length){[trackIds[i],trackIds[j]]=[trackIds[j],trackIds[i]];paint()}});trackRows.querySelectorAll('[data-unlink]').forEach(b=>b.onclick=()=>{trackIds=trackIds.filter(id=>id!==b.dataset.unlink);paint()})};paint();$('addTrackButton').onclick=()=>{const id=$('addTrack').value;if(id&&!trackIds.includes(id)){trackIds.push(id);$('addTrack').querySelector('option[value="'+id+'"]').remove();$('addTrack').value='';paint()}};$('saveTrackOrder').onclick=async()=>{const release=records.find(x=>x.id===releaseId);if(!release)return;const linked=records.filter(x=>x.type==='songs'&&x.releaseId===releaseId);try{await new Promise((res,rej)=>{const t=db.transaction(STORE,'readwrite'),store=t.objectStore(STORE);store.put({...release,trackOrder:trackIds,updated:new Date().toISOString()});for(const song of linked)if(!trackIds.includes(song.id))store.put({...song,releaseId:'',updated:new Date().toISOString()});for(const id of trackIds){const song=records.find(x=>x.id===id);if(song&&song.releaseId!==releaseId)store.put({...song,releaseId,updated:new Date().toISOString()})}t.oncomplete=()=>res();t.onerror=()=>rej(t.error)});toast('曲順と収録作品を保存しました');await refresh()}catch(e){toast('保存に失敗しました: '+e.message)}}};const setlistRows=$('setlistRows');if(setlistRows){const showId=editId;let songIds=Array.isArray(records.find(x=>x.id===showId)?.setlistSongIds)?[...records.find(x=>x.id===showId).setlistSongIds]:[];const paint=()=>{setlistRows.innerHTML=songIds.length?songIds.map((id,i)=>{const x=records.find(r=>r.id===id&&r.type==='songs');return '<div class="item"><div><span class="pill">#'+(i+1)+'</span> <strong>'+esc(x?.name||'削除された楽曲')+'</strong></div><div class="toolbar"><button type="button" class="outline" data-setmove="-1" data-index="'+i+'">↑</button><button type="button" class="outline" data-setmove="1" data-index="'+i+'">↓</button><button type="button" class="outline danger" data-setremove="'+i+'">外す</button></div></div>'}).join(''):'<p class="muted">まだ選択された楽曲はありません。</p>';setlistRows.querySelectorAll('[data-setmove]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.index),j=i+Number(b.dataset.setmove);if(j>=0&&j<songIds.length){[songIds[i],songIds[j]]=[songIds[j],songIds[i]];paint()}});setlistRows.querySelectorAll('[data-setremove]').forEach(b=>b.onclick=()=>{songIds.splice(Number(b.dataset.setremove),1);paint()})};paint();$('addSetlistButton').onclick=()=>{const id=$('addSetlistSong').value;if(id){songIds.push(id);paint()}};$('saveSetlistOrder').onclick=async()=>{const show=records.find(x=>x.id===showId);if(!show)return;try{await txn('readwrite',store=>store.put({...show,setlistSongIds:songIds,updated:new Date().toISOString()}));toast('セットリストを保存しました');await refresh()}catch(e){toast('保存に失敗しました: '+e.message)}}};const del=$('deleteRecord');if(del)del.onclick=async()=>{if(!confirm('このデータを削除しますか？'))return;await txn('readwrite',s=>s.delete(editId));editId=null;view=window.formType;toast('削除しました');await refresh()};const fl=$('filter');if(fl)fl.oninput=()=>{filter=fl.value;updateArchiveResults()};const gs=$('globalSearch');if(gs)gs.oninput=()=>{const q=gs.value.toLowerCase();$('searchResults').innerHTML=listItems(records.filter(r=>Object.entries(r).some(([k,v])=>k!=='id'&&typeof v==='string'&&v.toLowerCase().includes(q))).slice(0,100));attachResultButtons()};const ex=$('exportJson');if(ex)ex.onclick=async()=>{const data=JSON.stringify({app:'band-history-archive',schemaVersion:VERSION,exportedAt:new Date().toISOString(),records},null,2),name='band-archive-'+new Date().toISOString().slice(0,10)+'.json',file=new File([data],name,{type:'application/json'});try{if(navigator.canShare&&navigator.canShare({files:[file]})&&navigator.share){await navigator.share({files:[file],title:'Band History Archive バックアップ'});toast('共有メニューから「ファイルに保存」を選べます');return}}catch(e){if(e.name==='AbortError')return;console.warn('Share failed; falling back to download',e)}const url=URL.createObjectURL(new Blob([data],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('バックアップの保存を開始しました')};const imp=$('importJson');if(imp)imp.onchange=async()=>{const file=imp.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.app!=='band-history-archive'||!Array.isArray(data.records)||data.schemaVersion!==VERSION||!data.records.every(r=>r&&typeof r.id==='string'&&TYPES[r.type]&&typeof r.name==='string'))throw Error('対応していない形式です');if(!confirm(`${data.records.length}件のデータで現在の${records.length}件を置き換えます。続行しますか？`))return;await new Promise((res,rej)=>{const t=db.transaction(STORE,'readwrite'),s=t.objectStore(STORE);s.clear();for(const r of data.records)s.put(r);t.oncomplete=res;t.onerror=()=>rej(t.error)});toast('復元しました');await refresh()}catch(e){toast('読み込み失敗: '+e.message)}}}
function attachResultButtons(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{editId=b.dataset.detail;view='detail';render();window.scrollTo(0,0)});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const r=records.find(x=>x.id===b.dataset.edit);if(r){editId=r.id;window.formType=r.type;view='form';render()}})}
document.querySelectorAll('.bottom button').forEach(b=>b.onclick=()=>nav(b.dataset.view));$('modeButton').onclick=()=>{mode=mode==='management'?'official':mode==='official'?'encyclopedia':'management';render();toast('表示モードを切り替えました（詳細デザインは今後実装）')};
(async()=>{try{db=await openDB();await refresh()}catch(e){$('app').innerHTML='<div class="empty">データベースを開けませんでした。ブラウザのプライベートモードや保存設定をご確認ください。</div>';console.error(e)}})();